+	dir, err := ioutil.TempDir("", "flipt-migrator-test-")
+	require.NoError(t, err)
+	defer os.RemoveAll(dir)
+
+	migrations, err := filepath.Abs("../../config/migrations")
+	require.NoError(t, err)
+
+	cfg := config.Config{Database: config.DatabaseConfig{
+		Protocol:       config.SQLite,
+		Path:           dir,
+		Name:           "flipt.db",
+		MigrationsPath: migrations,
+		MaxIdleConn:    2,
+		MaxOpenConn:    3,
+	}}
+	migrator, err := NewMigrator(cfg, logrus.New())
+	require.NoError(t, err)
+	require.NoError(t, migrator.Run(false))
+	sourceErr, dbErr := migrator.Close()
+	require.NoError(t, sourceErr)
+	require.NoError(t, dbErr)
+
+	cfg.Database.Name = ""
+	_, err = NewMigrator(cfg, logrus.New())
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "db.name")
+}
